// Provider: 'api' uses Anthropic API (costs money), 'cli' uses Claude CLI (uses Max subscription)
const AI_PROVIDER = process.env.LUNAGRAPH_AI_PROVIDER || (process.env.ANTHROPIC_API_KEY ? 'api' : 'cli');
const anthropic = process.env.ANTHROPIC_API_KEY
