// Security: Validate path is within project root or allowed paths
function validatePath(filePath) {
    // Handle absolute paths - check if in allowed directories
    if (filePath.startsWith('/') || filePath.startsWith('~')) {
        const absolutePath = filePath.startsWith('~')
            ? join(process.env.HOME || '', filePath.slice(1))
            : filePath;
        // Check if path is within any allowed directory
        for (const allowedPath of ALLOWED_PATHS) {
            const rel = relative(allowedPath, absolutePath);
            if (!rel.startsWith('..') && !rel.startsWith('/')) {
                return absolutePath;
            }
        }
        // Also allow PROJECT_ROOT for absolute paths
        const relToProject = relative(PROJECT_ROOT, absolutePath);
        if (!relToProject.startsWith('..') && !relToProject.startsWith('/')) {
            return absolutePath;
        }
        return null; // Not in any allowed directory
    }
    // Relative path - resolve against PROJECT_ROOT
    const absolutePath = join(PROJECT_ROOT, filePath);
    const relativePath = relative(PROJECT_ROOT, absolutePath);
    if (relativePath.startsWith('..') || relativePath.startsWith('/')) {
        return null; // Path escape attempt
    }
    return absolutePath;
}
/**
 * Register a component in ComponentIndex.json and regenerate components.ts
 * Called when AI writes a component file
 */
async function registerComponent(filePath, contents) {
    // Only process .tsx files
    if (!filePath.endsWith('.tsx'))
        return { registered: false };
    // Check if file looks like a component (has export)
    const defaultExportMatch = contents.match(/export\s+default\s+function\s+(\w+)/);
    const namedExportMatch = contents.match(/export\s+(?:const|function)\s+(\w+)/);
    if (!defaultExportMatch && !namedExportMatch)
        return { registered: false };
    const componentName = defaultExportMatch?.[1] || namedExportMatch?.[1];
    if (!componentName)
        return { registered: false };
    // Check if it's in a reasonable location (components folder or .lunagraph)
    const isComponentPath = filePath.includes('components/') || filePath.includes('.lunagraph/');
    if (!isComponentPath)
        return { registered: false };
    try {
        const indexPath = join(PROJECT_ROOT, '.lunagraph', 'ComponentIndex.json');
        const componentsPath = join(PROJECT_ROOT, '.lunagraph', 'components.ts');
        const lunagraphDir = join(PROJECT_ROOT, '.lunagraph');
        await mkdir(lunagraphDir, { recursive: true });
        // Read existing index
        let index = {};
        try {
            const content = await readFile(indexPath, 'utf-8');
            index = JSON.parse(content);
        }
        catch {
            // Index doesn't exist yet
        }
        // Add new component
        index[componentName] = {
            path: filePath,
            exportName: defaultExportMatch ? 'default' : componentName
        };
        // Write updated ComponentIndex.json
        await writeFile(indexPath, JSON.stringify(index, null, 2), 'utf-8');
        // Regenerate components.ts
        const imports = [];
        const componentNames = [];
        for (const [name, info] of Object.entries(index)) {
            const importPath = info.path.replace(/\.tsx?$/, '');
            if (info.exportName === 'default') {
                imports.push(`import ${name} from '../${importPath}'`);
            }
            else {
                imports.push(`import { ${info.exportName} as ${name} } from '../${importPath}'`);
            }
            componentNames.push(name);
        }
        const componentsContent = `// Auto-generated by @lunagraph/dev-server - do not edit manually
// This file is updated automatically when components are created

${imports.join('\n')}
import componentIndexData from './ComponentIndex.json'

// Export all components
export { ${componentNames.join(', ')} }

// Export as components object
export const components = {
  ${componentNames.join(',\n  ')}
}

// Export component index
export const componentIndex = componentIndexData
`;
        await writeFile(componentsPath, componentsContent, 'utf-8');
        console.log(`✓ Registered component: ${componentName}`);
        return { registered: true, componentName };
    }
    catch (error) {
        console.error('Failed to register component:', error);
        return { registered: false };
    }
}
