function elementToJSX(el, indent = 0, highlightId) {
    const pad = '  '.repeat(indent);
    const isHighlighted = el.id === highlightId;
    const marker = isHighlighted ? ' {/* ← SELECTED */}' : '';
    if (el.type === 'text') {
        return `${pad}${el.text || ''}${marker}`;
    }
    // Handle icons specially with data-icon syntax
    if (el.type === 'icon') {
        const props = [`id="${el.id}"`, `data-icon="${el.iconName}"`];
        if (el.styles?.className)
            props.push(`className="${el.styles.className}"`);
        const propsStr = ' ' + props.join(' ');
        return `${pad}<i${propsStr} />${marker}`;
    }
    const props = [`id="${el.id}"`];
    if (el.type === 'html' || el.type === 'component') {
        if (el.styles?.className)
            props.push(`className="${el.styles.className}"`);
        const styleObj = {};
        if (el.styles) {
            for (const [key, value] of Object.entries(el.styles)) {
                if (key !== 'className' && value !== undefined)
                    styleObj[key] = value;
            }
        }
        if (Object.keys(styleObj).length > 0)
            props.push(`style={${JSON.stringify(styleObj)}}`);
        if (el.props) {
            for (const [key, value] of Object.entries(el.props)) {
                props.push(typeof value === 'string' ? `${key}="${value}"` : `${key}={${JSON.stringify(value)}}`);
            }
        }
    }
    const tagName = el.type === 'component' ? el.componentName :
        el.type === 'html' ? el.tag : 'unknown';
    const propsStr = props.length > 0 ? ' ' + props.join(' ') : '';
    if ('children' in el && el.children && el.children.length > 0) {
        const childrenJSX = el.children.map(c => elementToJSX(c, indent + 1, highlightId)).join('\n');
        return `${pad}<${tagName}${propsStr}>${marker}\n${childrenJSX}\n${pad}</${tagName}>`;
    }
    return `${pad}<${tagName}${propsStr} />${marker}`;
}
function canvasToJSX(elements) {
    if (elements.length === 0)
        return '// Empty canvas';
    return elements.map(el => elementToJSX(el, 0)).join('\n\n');
}
function buildContextTree(elements, targetId) {
    for (const root of elements) {
        if (root.id === targetId)
            return elementToJSX(root, 0, targetId);
        if ('children' in root && root.children) {
            const find = (els) => els.some(e => e.id === targetId || ('children' in e && e.children && find(e.children)));
            if (find(root.children))
                return elementToJSX(root, 0, targetId);
        }
    }
    return null;
}
