// Max image size: 500KB base64 (roughly 375KB actual file)
const MAX_IMAGE_BASE64_SIZE = 500_000;
async function extractImagesFromElement(element) {
    const images = [];
    if (!element)
        return images;
    // Only extract if THIS element is an <img> tag (don't recurse into children)
    // Children images would bloat the request - Claude sees the JSX structure anyway
    if (element.type === 'html' && element.tag === 'img' && element.props?.src) {
        const src = element.props.src;
        if (src.startsWith('/') || src.startsWith('.')) {
            try {
                const imagePath = src.startsWith('/.lunagraph-assets/') || src.startsWith('.lunagraph-assets/') || src.startsWith('/')
                    ? join(PROJECT_ROOT, 'public', src)
                    : join(PROJECT_ROOT, src);
                const imageBuffer = await readFile(imagePath);
                const base64 = imageBuffer.toString('base64');
                // Skip if too large
                if (base64.length > MAX_IMAGE_BASE64_SIZE) {
                    console.warn(`[AI Chat] Skipping large image: ${src} (${(base64.length / 1_000_000).toFixed(1)}MB)`);
                    return images;
                }
                const ext = src.split('.').pop()?.toLowerCase();
                let mediaType = 'image/png';
                if (ext === 'jpg' || ext === 'jpeg')
                    mediaType = 'image/jpeg';
                else if (ext === 'gif')
                    mediaType = 'image/gif';
                else if (ext === 'webp')
                    mediaType = 'image/webp';
                images.push({ path: src, base64, mediaType });
            }
            catch (err) {
                console.warn(`[AI Chat] Could not read image: ${src}`, err);
            }
        }
    }
    // Don't recursively extract children images - they bloat requests
    return images;
}
// Execute a native tool call from Claude CLI
async function executeNativeTool(toolName, input) {
    console.log(`[AI Chat] Executing native tool: ${toolName}`, JSON.stringify(input).slice(0, 100));
    if (toolName === 'Read' || toolName === 'read_file') {
        const filePath = input.path || input.file_path;
        const absPath = validatePath(filePath);
        if (!absPath) {
            return { result: `Error: Invalid path "${filePath}"` };
        }
        try {
            const content = await readFile(absPath, 'utf-8');
            console.log(`  → Read ${filePath} (${content.length} chars)`);
            return {
                result: content.slice(0, 10000), // Limit for context
                toolResult: { type: 'Read', payload: { path: filePath, content: '(read)' } }
            };
        }
        catch (e) {
            return { result: `Error reading file: ${e}` };
        }
    }
    // Claude CLI Edit tool uses str_replace format (old_str -> new_str)
    if (toolName === 'Edit' || toolName === 'edit_file' || toolName === 'str_replace_editor') {
        const filePath = input.path || input.file_path;
        const oldStr = input.old_str || input.old_string || input.search;
        const newStr = input.new_str || input.new_string || input.replace;
        const absPath = validatePath(filePath);
        if (!absPath) {
            return { result: `Error: Invalid path "${filePath}"` };
        }
        try {
            // Read current file
            let content = '';
            try {
                content = await readFile(absPath, 'utf-8');
            }
            catch {
                // File doesn't exist, that's okay for new files
            }
            if (oldStr && newStr !== undefined) {
                // str_replace mode
                if (!content.includes(oldStr)) {
                    console.log(`  → Edit failed: old_str not found in ${filePath}`);
                    return { result: `Error: Could not find the text to replace in ${filePath}` };
                }
                content = content.replace(oldStr, newStr);
            }
            else if (input.contents || input.content || input.new_content) {
                // Full file write mode
                content = input.contents || input.content || input.new_content;
            }
            else if (input.insert_line !== undefined && input.new_str) {
                // Insert at line mode
                const lines = content.split('\n');
                lines.splice(input.insert_line, 0, input.new_str);
                content = lines.join('\n');
            }
            else {
                console.log(`  → Edit: unknown format`, JSON.stringify(input).slice(0, 200));
                return { result: `Error: Unknown edit format` };
            }
            await mkdir(dirname(absPath), { recursive: true });
            await writeFile(absPath, content, 'utf-8');
            const registration = await registerComponent(filePath, content);
            console.log(`  → Edited ${filePath}${registration.registered ? ` (registered ${registration.componentName})` : ''}`);
            return {
                result: `Successfully edited ${filePath}`,
                toolResult: {
                    type: 'Write',
                    payload: {
                        path: filePath,
                        success: true,
                        componentRegistered: registration.registered,
                        componentName: registration.componentName
                    }
                }
            };
        }
        catch (e) {
            console.error(`  → Edit error:`, e);
            return { result: `Error editing file: ${e}` };
        }
    }
    // Full file write
    if (toolName === 'Write' || toolName === 'write_file') {
        const filePath = input.path || input.file_path;
        const contents = input.contents || input.content || input.new_content;
        const absPath = validatePath(filePath);
        if (!absPath) {
            return { result: `Error: Invalid path "${filePath}"` };
        }
        if (!contents) {
            return { result: `Error: No contents provided for write` };
        }
        try {
            await mkdir(dirname(absPath), { recursive: true });
            await writeFile(absPath, contents, 'utf-8');
            const registration = await registerComponent(filePath, contents);
            console.log(`  → Wrote ${filePath}${registration.registered ? ` (registered ${registration.componentName})` : ''}`);
            return {
                result: registration.registered
                    ? `Created component ${registration.componentName} at ${filePath}`
                    : `Successfully wrote ${filePath}`,
                toolResult: {
                    type: 'Write',
                    payload: {
                        path: filePath,
                        success: true,
                        componentRegistered: registration.registered,
                        componentName: registration.componentName
                    }
                }
            };
        }
        catch (e) {
            return { result: `Error writing file: ${e}` };
        }
    }
    if (toolName === 'LS' || toolName === 'list_directory') {
        const dirPath = input.path || input.directory || '.';
        const absPath = validatePath(dirPath);
        if (!absPath) {
            return { result: `Error: Invalid path "${dirPath}"` };
        }
        try {
            const entries = await readdir(absPath, { withFileTypes: true });
            const files = entries.map(e => `${e.isDirectory() ? '📁' : '📄'} ${e.name}`);
            return {
                result: files.join('\n'),
                toolResult: { type: 'LS', payload: { path: dirPath, files: entries.map(e => ({ name: e.name, type: e.isDirectory() ? 'directory' : 'file' })) } }
            };
        }
        catch (e) {
            return { result: `Error listing directory: ${e}` };
        }
    }
    if (toolName === 'Glob' || toolName === 'glob') {
        const pattern = input.pattern;
        try {
            const { globby } = await import('globby');
            const files = await globby(pattern, { cwd: PROJECT_ROOT, gitignore: true });
            return {
                result: files.slice(0, 50).join('\n'),
                toolResult: { type: 'Glob', payload: { pattern, files: files.slice(0, 50) } }
            };
        }
        catch (e) {
            return { result: `Error: ${e}` };
        }
    }
    // Unknown tool - just return acknowledgment
    console.log(`  → Unknown tool ${toolName}, skipping`);
    return { result: `Tool ${toolName} executed` };
}
// Run Claude CLI with stream-json format for image support
// Images are passed via stdin as proper content blocks
async function runClaudeCLI(prompt, res, images) {
    return new Promise((resolve, reject) => {
        // Use stream-json input/output format for image support
        // --verbose is required for stream-json output
        // Security: --tools limits to file operations only (no Bash!)
        // --permission-mode acceptEdits auto-accepts file writes
        const args = [
            '-p',
            '--input-format', 'stream-json',
            '--output-format', 'stream-json',
            '--verbose',
            '--tools', 'Read,Write,Edit,Glob,Grep',
            '--permission-mode', 'acceptEdits'
        ];
        console.log(`[AI Chat] CLI mode${images?.length ? ` with ${images.length} image(s)` : ''}`);
        if (images?.length) {
            images.forEach((img, i) => {
                console.log(`  Image ${i}: mediaType=${img.mediaType}, base64 length=${img.base64?.length || 0}`);
            });
        }
        const claude = spawn('claude', args, {
            cwd: PROJECT_ROOT,
            shell: false,
            env: { ...process.env },
        });
        let fullText = '';
        let stderrOutput = '';
        const nativeToolResults = [];
        const pendingToolCalls = [];
        // Buffer for incomplete lines (JSON can be split across chunks)
        let lineBuffer = '';
        claude.stdout.on('data', (data) => {
            const chunk = data.toString();
            console.log(`[AI Chat] stdout chunk: ${chunk.length} bytes`);
            lineBuffer += chunk;
            const lines = lineBuffer.split('\n');
            // Keep the last potentially incomplete line in the buffer
            lineBuffer = lines.pop() || '';
            for (const line of lines) {
                if (!line.trim())
                    continue;
                try {
                    const event = JSON.parse(line);
                    console.log(`[AI Chat] event type: ${event.type}`);
                    // Handle different event types from stream-json output
                    if (event.type === 'assistant' && event.message?.content) {
                        for (const block of event.message.content) {
                            if (block.type === 'text') {
                                // Stream text to client
                                res.write(`data: ${JSON.stringify({ type: 'text', content: block.text })}\n\n`);
                                fullText += block.text;
                            }
                            else if (block.type === 'tool_use') {
                                // Collect native tool calls to execute after CLI closes
                                console.log(`[AI Chat] Native tool_use: ${block.name}`);
                                pendingToolCalls.push({ id: block.id, name: block.name, input: block.input });
                            }
                        }
                    }
                    else if (event.type === 'result') {
                        // Final result - always stream it
                        if (event.result) {
                            res.write(`data: ${JSON.stringify({ type: 'text', content: event.result })}\n\n`);
                            // Append to fullText for tool parsing
                            fullText += '\n' + event.result;
                        }
                    }
                }
                catch {
                    // Ignore parse errors for partial JSON lines
                }
            }
        });
        claude.stderr.on('data', (data) => {
            const chunk = data.toString();
            console.log(`[AI Chat] stderr: ${chunk}`);
            stderrOutput += chunk;
        });
        claude.on('close', async (code) => {
            console.log('Claude CLI closed with code:', code);
            // Process any remaining buffered content
            if (lineBuffer.trim()) {
                try {
                    const event = JSON.parse(lineBuffer);
                    if (event.type === 'result' && event.result) {
                        if (!fullText)
                            fullText = event.result;
                        res.write(`data: ${JSON.stringify({ type: 'text', content: event.result })}\n\n`);
                    }
                }
                catch {
                    // Ignore
                }
            }
            if (code !== 0) {
                console.error('Claude CLI stderr:', stderrOutput);
                reject(new Error(`Claude CLI exited with code ${code}. stderr: ${stderrOutput}`));
                return;
            }
            // Execute pending native tool calls
            if (pendingToolCalls.length > 0) {
                console.log(`[AI Chat] Executing ${pendingToolCalls.length} native tool calls...`);
                for (const toolCall of pendingToolCalls) {
                    const { toolResult } = await executeNativeTool(toolCall.name, toolCall.input);
                    if (toolResult) {
                        nativeToolResults.push(toolResult);
                    }
                }
            }
            console.log(`[AI Chat] CLI response length: ${fullText.length} chars, native tools: ${nativeToolResults.length}`);
            resolve({ text: fullText, nativeToolResults });
        });
        claude.on('error', (err) => {
            console.error('Claude CLI spawn error:', err);
            reject(err);
        });
        // Build message content with images and text
        const contentBlocks = [];
        // Add images first (before text for better performance)
        // Skip images larger than 1MB base64 (roughly 750KB actual) to avoid CLI crashes
        const MAX_IMAGE_SIZE = 1_000_000;
        if (images && images.length > 0) {
            for (const img of images) {
                if (img.base64 && img.base64.length > MAX_IMAGE_SIZE) {
                    console.log(`  Skipping image: too large (${(img.base64.length / 1_000_000).toFixed(1)}MB > 1MB limit)`);
                    continue;
                }
                contentBlocks.push({
                    type: 'image',
                    source: {
                        type: 'base64',
                        media_type: img.mediaType,
                        data: img.base64
                    }
                });
            }
        }
        // Add the text prompt
        contentBlocks.push({
            type: 'text',
            text: prompt
        });
        // Create the stream-json input message
        const inputMessage = {
            type: 'user',
            message: {
                role: 'user',
                content: contentBlocks
            }
        };
        // Write the JSON message to stdin and close it
        claude.stdin.write(JSON.stringify(inputMessage) + '\n');
        claude.stdin.end();
    });
}
// Parse tool calls from Claude CLI text response
// This is async because file operations need to be executed
async function parseToolCallsFromText(text, context) {
    const toolResults = [];
    // Look for code blocks with tool calls
    // Pattern: ```tool:ToolName ... ``` or ```ToolName {...} ```
    // Use \s* to match optional whitespace (including newlines) after tool name
    const toolBlockRegex = /```(?:tool:)?(\w+)\s*([\s\S]*?)```/g;
    let match;
    while ((match = toolBlockRegex.exec(text)) !== null) {
        const toolName = match[1];
        const content = match[2].trim();
        console.log(`Parsing tool call: ${toolName}`, content.slice(0, 100));
        try {
            // === CANVAS OPERATIONS ===
            if (toolName === 'AddToCanvas' || toolName === 'jsx') {
                const parsedElements = parseJSX(content, undefined, undefined, context.iconLibraryName);
                if (parsedElements.length > 0) {
                    console.log(`  → Parsed ${parsedElements.length} elements for AddToCanvas`);
                    toolResults.push({
                        type: 'add_jsx',
                        payload: { elements: parsedElements, originalJsx: content },
                    });
                }
            }
            else if (toolName === 'UpdateElement') {
                // Try to parse JSON format { elementId, jsx }
                const parsed = JSON.parse(content);
                const parsedElements = parseJSX(parsed.jsx, undefined, undefined, context.iconLibraryName);
                if (parsedElements.length > 0) {
                    console.log(`  → Parsed UpdateElement for ${parsed.elementId}`);
                    toolResults.push({
                        type: 'update_jsx',
                        payload: { elementId: parsed.elementId, newElement: parsedElements[0], originalJsx: parsed.jsx },
                    });
                }
            }
            else if (toolName === 'DeleteElement') {
                // Parse JSON format { elementId }
                const parsed = JSON.parse(content);
                console.log(`  → Parsed DeleteElement for ${parsed.elementId}`);
                toolResults.push({
                    type: 'delete_element',
                    payload: { elementId: parsed.elementId },
                });
            }
            else if (toolName === 'ReplaceWithComponent') {
                // Parse JSON format { elementId, componentName, props? }
                const parsed = JSON.parse(content);
                console.log(`  → Parsed ReplaceWithComponent: ${parsed.elementId} → ${parsed.componentName}`);
                toolResults.push({
                    type: 'replace_with_component',
                    payload: {
                        elementId: parsed.elementId,
                        componentName: parsed.componentName,
                        props: parsed.props || {}
                    },
                });
            }
            // === FILE OPERATIONS (CLI mode - must actually execute these!) ===
            else if (toolName === 'Write') {
                // Parse JSON format { path, contents }
                const parsed = JSON.parse(content);
                const absPath = validatePath(parsed.path);
                if (!absPath) {
                    console.error(`  → Write failed: Invalid path ${parsed.path}`);
                    toolResults.push({ type: 'Write', payload: { path: parsed.path, error: 'Invalid path' } });
                }
                else {
                    try {
                        await mkdir(dirname(absPath), { recursive: true });
                        await writeFile(absPath, parsed.contents, 'utf-8');
                        // Auto-register component if it's a .tsx file in components folder
                        const registration = await registerComponent(parsed.path, parsed.contents);
                        if (registration.registered) {
                            console.log(`  → Created and registered component: ${registration.componentName}`);
                        }
                        else {
                            console.log(`  → Wrote file: ${parsed.path}`);
                        }
                        toolResults.push({
                            type: 'Write',
                            payload: {
                                path: parsed.path,
                                success: true,
                                componentRegistered: registration.registered,
                                componentName: registration.componentName
                            }
                        });
                    }
                    catch (e) {
                        console.error(`  → Write failed:`, e);
                        toolResults.push({ type: 'Write', payload: { path: parsed.path, error: String(e) } });
                    }
                }
            }
            else if (toolName === 'Read') {
                // Parse JSON format { path } - Actually execute in CLI mode for agentic loop
                const parsed = JSON.parse(content);
                const absPath = validatePath(parsed.path);
                if (!absPath) {
                    console.log(`  → Read failed: Invalid path ${parsed.path}`);
                    toolResults.push({ type: 'Read', payload: { path: parsed.path, error: 'Invalid path' } });
                }
                else {
                    try {
                        const fileContents = await readFile(absPath, 'utf-8');
                        console.log(`  → Read file: ${parsed.path} (${fileContents.length} chars)`);
                        toolResults.push({ type: 'Read', payload: { path: parsed.path, contents: fileContents } });
                    }
                    catch (e) {
                        console.log(`  → Read failed: ${e}`);
                        toolResults.push({ type: 'Read', payload: { path: parsed.path, error: String(e) } });
                    }
                }
            }
            else if (toolName === 'LS') {
                // Parse JSON format { path } - Actually execute in CLI mode for agentic loop
                const parsed = JSON.parse(content);
                const absPath = validatePath(parsed.path || '.');
                if (!absPath) {
                    console.log(`  → LS failed: Invalid path ${parsed.path}`);
                    toolResults.push({ type: 'LS', payload: { path: parsed.path, error: 'Invalid path' } });
                }
                else {
                    try {
                        const entries = await readdir(absPath, { withFileTypes: true });
                        const files = entries.map(e => ({ name: e.name, isDirectory: e.isDirectory() }));
                        console.log(`  → LS: ${parsed.path} (${files.length} entries)`);
                        toolResults.push({ type: 'LS', payload: { path: parsed.path, files } });
                    }
                    catch (e) {
                        console.log(`  → LS failed: ${e}`);
                        toolResults.push({ type: 'LS', payload: { path: parsed.path, error: String(e) } });
                    }
                }
            }
            else if (toolName === 'Glob') {
                // Parse JSON format { pattern } - Actually execute in CLI mode for agentic loop
                const parsed = JSON.parse(content);
                try {
                    const { globby } = await import('globby');
                    const matches = await globby(parsed.pattern, { cwd: PROJECT_ROOT, gitignore: true });
                    console.log(`  → Glob: ${parsed.pattern} (${matches.length} matches)`);
                    toolResults.push({ type: 'Glob', payload: { pattern: parsed.pattern, matches } });
                }
                catch (e) {
                    console.log(`  → Glob failed: ${e}`);
                    toolResults.push({ type: 'Glob', payload: { pattern: parsed.pattern, error: String(e) } });
                }
            }
        }
        catch (e) {
            console.error(`Failed to parse ${toolName} tool call:`, e);
            console.error('Content was:', content.slice(0, 200));
        }
    }
    console.log(`Parsed ${toolResults.length} tool results from text`);
    return toolResults;
}
// Streaming chat handler - sends SSE
export async function handleChatStream(messages, context, res) {
    const systemPrompt = buildSystemPrompt(context);
    // Extract images from selected element
    const elementImages = await extractImagesFromElement(context.selectedElement);
    // Also extract images from attached elements (Cmd+L referenced elements)
    if (context.attachedElements) {
        for (const attachedEl of context.attachedElements) {
            const attachedImages = await extractImagesFromElement(attachedEl);
            elementImages.push(...attachedImages);
        }
    }
    const inlineImages = [];
    if (context.inlineRefs) {
        for (const ref of context.inlineRefs) {
            if (ref.type === 'image' && ref.data) {
                const match = ref.data.match(/^data:(image\/[^;]+);base64,(.+)$/);
                if (match) {
                    const base64 = match[2];
                    // Skip if too large (500KB base64 limit)
                    if (base64.length > MAX_IMAGE_BASE64_SIZE) {
                        console.warn(`[AI Chat] Skipping large inline image: ${ref.name} (${(base64.length / 1_000_000).toFixed(1)}MB)`);
                        continue;
                    }
                    inlineImages.push({ name: ref.name, base64, mediaType: match[1] });
                }
            }
        }
    }
    const allImages = [...elementImages, ...inlineImages.map(img => ({
            path: img.name, base64: img.base64,
            mediaType: img.mediaType
        }))];
    // Build messages
    const anthropicMessages = messages.map((m, i) => {
        if (m.role === 'user' && i === messages.length - 1 && allImages.length > 0) {
            return {
                role: 'user',
                content: [
                    ...allImages.map(img => ({
                        type: 'image',
                        source: { type: 'base64', media_type: img.mediaType, data: img.base64 },
                    })),
                    { type: 'text', text: m.content },
                ],
            };
        }
        return { role: m.role, content: m.content };
    });
    // Set up SSE
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    const toolResults = [];
    let fullText = '';
    try {
        // Use CLI or API based on provider
        if (AI_PROVIDER === 'cli') {
            // Build full prompt for CLI (no tool calling, just prompt engineering)
            const lastUserMessage = messages[messages.length - 1]?.content || '';
            const fullPrompt = `${systemPrompt}

## Tool Format

Use these code block formats. The tool name must be on the first line right after the triple backticks.

### FILE OPERATIONS

#### Write a file (auto-registers components!):
\`\`\`Write
{"path": "components/MyComponent.tsx", "contents": "export function MyComponent() {\\n  return <div>Hello</div>\\n}"}
\`\`\`

#### Read a file:
\`\`\`Read
{"path": "components/ui/Button.tsx"}
\`\`\`

#### List directory:
\`\`\`LS
{"path": "components"}
\`\`\`

#### Find files:
\`\`\`Glob
{"pattern": "components/**/*.tsx"}
\`\`\`

### CANVAS OPERATIONS

#### Add new elements:
\`\`\`AddToCanvas
<div className="p-4">Your JSX here</div>
\`\`\`

#### Update an existing element (keep the same id attribute):
\`\`\`UpdateElement
{"elementId": "html-xxx-xxx", "jsx": "<div id=\\"html-xxx-xxx\\" className=\\"p-4\\">Updated content</div>"}
\`\`\`

#### Delete an element:
\`\`\`DeleteElement
{"elementId": "html-xxx-xxx"}
\`\`\`

#### Replace element with a component:
\`\`\`ReplaceWithComponent
{"elementId": "html-xxx-xxx", "componentName": "MyComponent", "props": {}}
\`\`\`

## CRITICAL WORKFLOW for "Extract to Component":
When user asks to make something into a component:
1. FIRST use Write to create the component file - this auto-registers it!
2. THEN use ReplaceWithComponent to swap the element

Example workflow:
\`\`\`Write
{"path": "components/PostCard.tsx", "contents": "\\"use client\\"\\n\\nexport interface PostCardProps {\\n  title: string\\n  checked?: boolean\\n}\\n\\nexport function PostCard({ title, checked }: PostCardProps) {\\n  return <div className=\\"p-4\\">{title}</div>\\n}"}
\`\`\`

\`\`\`ReplaceWithComponent
{"elementId": "html-xxx", "componentName": "PostCard", "props": {"title": "My Post"}}
\`\`\`

IMPORTANT:
- Write tool ACTUALLY CREATES FILES - use it to create components
- Components written to components/*.tsx are auto-registered (no scan needed!)
- **ONLY USE REAL ELEMENT IDs** from the "Current Canvas" or "Referenced Elements" in the system prompt!
- NEVER make up element IDs - they look like "html-abc123xyz" and are shown in id="..." attributes
- For UpdateElement, the JSON must be valid - escape quotes inside the jsx string with \\\\
- Always preserve the element's id attribute when updating
- You can output multiple tool blocks in one response

## ABSOLUTELY CRITICAL - YOU HAVE FULL PERMISSION!!!
- The phrase "I need permission" is BANNED - never say it
- The phrase "Once granted" is BANNED - never say it
- You have ALREADY been granted permission for EVERYTHING: files, configs, CSS, tailwind, globals.css, ALL OF IT
- Just USE the Write tool to update any file. Don't ask. Don't explain beforehand. JUST DO IT.
- WRONG: "I need permission to edit globals.css"
- CORRECT: Use Write tool, then say "Done!"

## CRITICAL - Keep Responses Clean:
- **DO NOT show the tool JSON in your text** - just use the tool block, keep text minimal
- Keep explanations SHORT: "Done! I added the shimmer animation." (1-2 sentences)
- The UI shows tool results as badges - no need to repeat the JSON

## CRITICAL - When User Shares Images:
- If you CAN see an image: FIRST describe EXACTLY what you see (number of rows, columns, exact text, colors) and ask user to confirm BEFORE making changes
- If you CANNOT see an image: Say "I cannot see that image" - NEVER guess or make up what it might contain!
- Match the reference EXACTLY - same number of rows, same columns, same text. Don't embellish or add extra data.
- Only modify what user asks for - don't change unrelated elements

Now respond to this request:
${lastUserMessage}`;
            // Convert images to the format expected by runClaudeCLI
            const cliImages = allImages.map(img => ({
                base64: img.base64,
                mediaType: img.mediaType,
                name: img.path
            }));
            // CLI mode with agentic loop - continue when file operations need results
            const MAX_CLI_ITERATIONS = 10;
            let currentPrompt = fullPrompt;
            let conversationHistory = [];
            for (let iteration = 0; iteration < MAX_CLI_ITERATIONS; iteration++) {
                console.log(`[AI Chat] CLI iteration ${iteration + 1}...`);
                // Build prompt with conversation history for continuation
                let iterationPrompt = currentPrompt;
                if (conversationHistory.length > 0) {
                    iterationPrompt = conversationHistory.map(m => `${m.role === 'user' ? 'User' : 'Assistant'}: ${m.content}`).join('\n\n') + '\n\nUser: ' + currentPrompt;
                }
                const result = await runClaudeCLI(iterationPrompt, res, iteration === 0 ? cliImages : undefined);
                fullText += result.text;
                // Add native tool results (executed by runClaudeCLI)
                if (result.nativeToolResults && result.nativeToolResults.length > 0) {
                    console.log(`[AI Chat] Adding ${result.nativeToolResults.length} native tool results`);
                    toolResults.push(...result.nativeToolResults);
                }
                // Parse tool calls from the response text (and execute file operations)
                const parsedTools = await parseToolCallsFromText(result.text, context);
                toolResults.push(...parsedTools);
                // Check if there are file operation results that need to be fed back
                const fileOpResults = parsedTools.filter(t => t.type === 'Read' || t.type === 'LS' || t.type === 'Glob');
                // If no file operations or all file operations failed, we're done
                const hasSuccessfulFileOps = fileOpResults.some(t => {
                    const payload = t.payload;
                    return !payload.error && (payload.contents || payload.files || payload.matches);
                });
                if (!hasSuccessfulFileOps) {
                    console.log(`[AI Chat] CLI iteration ${iteration + 1}: No more file ops to continue, finishing...`);
                    break;
                }
                // Build continuation prompt with file operation results
                const fileResultsSummary = fileOpResults.map(t => {
                    const payload = t.payload;
                    if (t.type === 'Read') {
                        if (payload.error)
                            return `Read ${payload.path}: ERROR - ${payload.error}`;
                        return `Read ${payload.path}:\n\`\`\`\n${payload.contents}\n\`\`\``;
                    }
                    else if (t.type === 'LS') {
                        if (payload.error)
                            return `LS ${payload.path}: ERROR - ${payload.error}`;
                        const files = payload.files;
                        return `LS ${payload.path}:\n${files.map(f => `  ${f.isDirectory ? '[DIR] ' : ''}${f.name}`).join('\n')}`;
                    }
                    else if (t.type === 'Glob') {
                        if (payload.error)
                            return `Glob ${payload.pattern}: ERROR - ${payload.error}`;
                        const matches = payload.matches;
                        if (matches.length === 0)
                            return `Glob ${payload.pattern}: No matches found`;
                        return `Glob ${payload.pattern}:\n${matches.map(m => `  ${m}`).join('\n')}`;
                    }
                    return '';
                }).filter(Boolean).join('\n\n');
                // Add to conversation history
                conversationHistory.push({ role: 'assistant', content: result.text });
                conversationHistory.push({ role: 'user', content: `Here are the results of your file operations:\n\n${fileResultsSummary}\n\nPlease continue with your task using these results.` });
                // Update prompt for next iteration
                currentPrompt = `Here are the results of your file operations:\n\n${fileResultsSummary}\n\nPlease continue with your task using these results.`;
                console.log(`[AI Chat] CLI iteration ${iteration + 1}: Continuing with ${fileOpResults.length} file operation results...`);
            }
            // Send tool results
            if (toolResults.length > 0) {
                res.write(`data: ${JSON.stringify({ type: 'tools', results: toolResults })}\n\n`);
            }
            res.write(`data: ${JSON.stringify({ type: 'done', fullText })}\n\n`);
            res.end();
            return;
        }
        // API mode with agentic loop
        if (!anthropic) {
            throw new Error('ANTHROPIC_API_KEY not set and CLI not available');
        }
        // Keep conversation messages for the agentic loop
        let loopMessages = [...anthropicMessages];
        const MAX_ITERATIONS = 10;
        for (let iteration = 0; iteration < MAX_ITERATIONS; iteration++) {
            console.log(`AI iteration ${iteration + 1}...`);
            // Use Sonnet for cost efficiency (~10x cheaper than Opus)
            // Set LUNAGRAPH_AI_MODEL=claude-opus-4-20250514 to use Opus
            const model = process.env.LUNAGRAPH_AI_MODEL || 'claude-sonnet-4-20250514';
            const stream = anthropic.messages.stream({
                model,
                max_tokens: 4096,
                system: systemPrompt,
                tools,
                messages: loopMessages,
            });
            // Stream text to client
            for await (const event of stream) {
                if (event.type === 'content_block_delta') {
                    if (event.delta.type === 'text_delta') {
                        fullText += event.delta.text;
                        res.write(`data: ${JSON.stringify({ type: 'text', content: event.delta.text })}\n\n`);
                    }
                }
            }
            const finalMessage = await stream.finalMessage();
            // Check if there are any tool calls
            const toolUseBlocks = finalMessage.content.filter(b => b.type === 'tool_use');
            if (toolUseBlocks.length === 0) {
                // No tool calls, we're done
                console.log('No more tool calls, finishing...');
                break;
            }
            // Process tool calls and build results for Claude
            const toolResultsForClaude = [];
            for (const block of toolUseBlocks) {
                if (block.type !== 'tool_use')
                    continue;
                const input = block.input;
                let resultContent = '';
                // Canvas operations - these go to UI, not back to Claude
                if (block.name === 'AddToCanvas' || block.name === 'add_jsx') {
                    try {
                        const parsedElements = parseJSX(input.jsx, undefined, undefined, context.iconLibraryName);
                        toolResults.push({
                            type: 'add_jsx',
                            payload: { elements: parsedElements, parentId: input.parentId, originalJsx: input.jsx },
                        });
                        resultContent = `Added ${parsedElements.length} element(s) to canvas`;
                    }
                    catch (e) {
                        resultContent = `Error: ${e}`;
                    }
                }
                else if (block.name === 'UpdateElement' || block.name === 'update_jsx') {
                    try {
                        const parsedElements = parseJSX(input.jsx, undefined, undefined, context.iconLibraryName);
                        if (parsedElements.length > 0) {
                            toolResults.push({
                                type: 'update_jsx',
                                payload: { elementId: input.elementId, newElement: parsedElements[0], originalJsx: input.jsx },
                            });
                            resultContent = `Updated element ${input.elementId}`;
                        }
                    }
                    catch (e) {
                        resultContent = `Error: ${e}`;
                    }
                }
                else if (block.name === 'DeleteElement' || block.name === 'delete_element') {
                    toolResults.push({ type: 'delete_element', payload: { elementId: input.elementId } });
                    resultContent = `Deleted element ${input.elementId}`;
                }
                else if (block.name === 'ReplaceWithComponent') {
                    toolResults.push({
                        type: 'replace_with_component',
                        payload: {
                            elementId: input.elementId,
                            componentName: input.componentName,
                            props: input.props || {}
                        }
                    });
                    resultContent = `Replaced element with component ${input.componentName}`;
                }
                // File operations - results go back to Claude
                else if (block.name === 'Read') {
                    try {
                        const absPath = validatePath(input.path);
                        if (!absPath) {
                            resultContent = 'Error: Invalid path';
                            toolResults.push({ type: 'Read', payload: { path: input.path, error: 'Invalid path' } });
                        }
                        else {
                            const content = await readFile(absPath, 'utf-8');
                            resultContent = content.slice(0, 10000); // Limit to avoid token overflow
                            toolResults.push({ type: 'Read', payload: { path: input.path, content: '(read successfully)' } });
                        }
                    }
                    catch (e) {
                        resultContent = `Error reading file: ${e}`;
                        toolResults.push({ type: 'Read', payload: { path: input.path, error: String(e) } });
                    }
                }
                else if (block.name === 'Write') {
                    try {
                        const absPath = validatePath(input.path);
                        if (!absPath) {
                            resultContent = 'Error: Invalid path';
                            toolResults.push({ type: 'Write', payload: { path: input.path, error: 'Invalid path' } });
                        }
                        else {
                            await mkdir(dirname(absPath), { recursive: true });
                            await writeFile(absPath, input.contents, 'utf-8');
                            const registration = await registerComponent(input.path, input.contents);
                            resultContent = registration.registered
                                ? `Created component ${registration.componentName} at ${input.path}`
                                : `Wrote file ${input.path}`;
                            toolResults.push({
                                type: 'Write',
                                payload: {
                                    path: input.path,
                                    success: true,
                                    componentRegistered: registration.registered,
                                    componentName: registration.componentName
                                }
                            });
                        }
                    }
                    catch (e) {
                        resultContent = `Error writing file: ${e}`;
                        toolResults.push({ type: 'Write', payload: { path: input.path, error: String(e) } });
                    }
                }
                else if (block.name === 'LS') {
                    try {
                        const absPath = validatePath(input.path || '.');
                        if (!absPath) {
                            resultContent = 'Error: Invalid path';
                            toolResults.push({ type: 'LS', payload: { path: input.path, error: 'Invalid path' } });
                        }
                        else {
                            const entries = await readdir(absPath, { withFileTypes: true });
                            const files = entries.map(e => `${e.isDirectory() ? '📁' : '📄'} ${e.name}`);
                            resultContent = files.join('\n');
                            toolResults.push({ type: 'LS', payload: { path: input.path, files: entries.map(e => ({ name: e.name, type: e.isDirectory() ? 'directory' : 'file' })) } });
                        }
                    }
                    catch (e) {
                        resultContent = `Error listing directory: ${e}`;
                        toolResults.push({ type: 'LS', payload: { path: input.path, error: String(e) } });
                    }
                }
                else if (block.name === 'Glob') {
                    try {
                        const { globby } = await import('globby');
                        const files = await globby(input.pattern, { cwd: PROJECT_ROOT, gitignore: true });
                        resultContent = files.slice(0, 50).join('\n');
                        toolResults.push({ type: 'Glob', payload: { pattern: input.pattern, files: files.slice(0, 50) } });
                        // Send intermediate update to UI
                        res.write(`data: ${JSON.stringify({ type: 'text', content: `\n[Found ${files.length} files]\n` })}\n\n`);
                    }
                    catch (e) {
                        resultContent = `Error: ${e}`;
                        toolResults.push({ type: 'Glob', payload: { pattern: input.pattern, error: String(e) } });
                    }
                }
                toolResultsForClaude.push({
                    type: 'tool_result',
                    tool_use_id: block.id,
                    content: resultContent,
                });
            }
            // Send tool results to UI
            if (toolResults.length > 0) {
                res.write(`data: ${JSON.stringify({ type: 'tools', results: toolResults })}\n\n`);
            }
            // Add assistant response and tool results to conversation for next iteration
            loopMessages.push({
                role: 'assistant',
                content: finalMessage.content,
            });
            loopMessages.push({
                role: 'user',
                content: toolResultsForClaude,
            });
            // If Claude only made canvas operations (no file ops), we might be done
            const hasFileOps = toolUseBlocks.some(b => b.type === 'tool_use' && ['Read', 'Write', 'LS', 'Glob'].includes(b.name));
            if (!hasFileOps) {
                console.log('Only canvas operations, finishing...');
                break;
            }
        }
        res.write(`data: ${JSON.stringify({ type: 'done', fullText })}\n\n`);
        res.end();
    }
    catch (error) {
        console.error('Stream error:', error);
        res.write(`data: ${JSON.stringify({ type: 'error', message: String(error) })}\n\n`);
        res.end();
    }
}
// Non-streaming (compatibility)
export async function handleChat(messages, context) {
    const systemPrompt = buildSystemPrompt(context);
    // Extract images from selected element
    const elementImages = await extractImagesFromElement(context.selectedElement);
    // Also extract images from attached elements (Cmd+L referenced elements)
    if (context.attachedElements) {
        for (const attachedEl of context.attachedElements) {
            const attachedImages = await extractImagesFromElement(attachedEl);
            elementImages.push(...attachedImages);
        }
    }
    const inlineImages = [];
    if (context.inlineRefs) {
        for (const ref of context.inlineRefs) {
            if (ref.type === 'image' && ref.data) {
                const match = ref.data.match(/^data:(image\/[^;]+);base64,(.+)$/);
                if (match) {
                    const base64 = match[2];
                    // Skip if too large (500KB base64 limit)
                    if (base64.length > MAX_IMAGE_BASE64_SIZE) {
                        console.warn(`[AI Chat] Skipping large inline image: ${ref.name} (${(base64.length / 1_000_000).toFixed(1)}MB)`);
                        continue;
                    }
                    inlineImages.push({ name: ref.name, base64, mediaType: match[1] });
                }
            }
        }
    }
    const allImages = [...elementImages, ...inlineImages.map(img => ({
            path: img.name, base64: img.base64,
            mediaType: img.mediaType
        }))];
    const anthropicMessages = messages.map((m, i) => {
        if (m.role === 'user' && i === messages.length - 1 && allImages.length > 0) {
            return {
                role: 'user',
                content: [
                    ...allImages.map(img => ({
                        type: 'image',
                        source: { type: 'base64', media_type: img.mediaType, data: img.base64 },
                    })),
                    { type: 'text', text: m.content },
                ],
            };
        }
        return { role: m.role, content: m.content };
    });
    if (!anthropic) {
        throw new Error('ANTHROPIC_API_KEY not set');
    }
    // Use Sonnet for cost efficiency (~10x cheaper than Opus)
    // Set LUNAGRAPH_AI_MODEL=claude-opus-4-20250514 to use Opus
    const model = process.env.LUNAGRAPH_AI_MODEL || 'claude-sonnet-4-20250514';
    const response = await anthropic.messages.create({
        model,
        max_tokens: 4096,
        system: systemPrompt,
        tools,
        messages: anthropicMessages,
    });
    const toolResults = [];
    let textResponse = '';
    for (const block of response.content) {
        if (block.type === 'text') {
            textResponse += block.text;
        }
        else if (block.type === 'tool_use') {
            const input = block.input;
            // Canvas operations
            if (block.name === 'AddToCanvas' || block.name === 'add_jsx') {
                try {
                    toolResults.push({
                        type: 'add_jsx',
                        payload: { elements: parseJSX(input.jsx, undefined, undefined, context.iconLibraryName), parentId: input.parentId, originalJsx: input.jsx },
                    });
                }
                catch (e) {
                    console.error('Parse error:', e);
                }
            }
            else if (block.name === 'UpdateElement' || block.name === 'update_jsx') {
                try {
                    const parsed = parseJSX(input.jsx, undefined, undefined, context.iconLibraryName);
                    if (parsed.length > 0) {
                        toolResults.push({
                            type: 'update_jsx',
                            payload: { elementId: input.elementId, newElement: parsed[0], originalJsx: input.jsx },
                        });
                    }
                }
                catch (e) {
                    console.error('Parse error:', e);
                }
            }
            else if (block.name === 'DeleteElement' || block.name === 'delete_element') {
                toolResults.push({ type: 'delete_element', payload: { elementId: input.elementId } });
            }
            else if (block.name === 'ReplaceWithComponent') {
                toolResults.push({
                    type: 'replace_with_component',
                    payload: {
                        elementId: input.elementId,
                        componentName: input.componentName,
                        props: input.props || {}
                    }
                });
            }
            // File operations handled the same as streaming version
            else if (block.name === 'Read') {
                try {
                    const absPath = validatePath(input.path);
                    if (!absPath) {
                        toolResults.push({ type: 'Read', payload: { path: input.path, error: 'Invalid path' } });
                    }
                    else {
                        const content = await readFile(absPath, 'utf-8');
                        toolResults.push({ type: 'Read', payload: { path: input.path, content } });
                    }
                }
                catch (e) {
                    toolResults.push({ type: 'Read', payload: { path: input.path, error: String(e) } });
                }
            }
            else if (block.name === 'Write') {
                try {
                    const absPath = validatePath(input.path);
                    if (!absPath) {
                        toolResults.push({ type: 'Write', payload: { path: input.path, error: 'Invalid path' } });
                    }
                    else {
                        await mkdir(dirname(absPath), { recursive: true });
                        await writeFile(absPath, input.contents, 'utf-8');
                        // Auto-register if it's a component file
                        const registration = await registerComponent(input.path, input.contents);
                        toolResults.push({
                            type: 'Write',
                            payload: {
                                path: input.path,
                                success: true,
                                componentRegistered: registration.registered,
                                componentName: registration.componentName
                            }
                        });
                    }
                }
                catch (e) {
                    toolResults.push({ type: 'Write', payload: { path: input.path, error: String(e) } });
                }
            }
            else if (block.name === 'LS') {
                try {
                    const absPath = validatePath(input.path || '.');
                    if (!absPath) {
                        toolResults.push({ type: 'LS', payload: { path: input.path, error: 'Invalid path' } });
                    }
                    else {
                        const entries = await readdir(absPath, { withFileTypes: true });
                        const files = entries.map(e => ({
                            name: e.name,
                            type: e.isDirectory() ? 'directory' : 'file'
                        }));
                        toolResults.push({ type: 'LS', payload: { path: input.path, files } });
                    }
                }
                catch (e) {
                    toolResults.push({ type: 'LS', payload: { path: input.path, error: String(e) } });
                }
            }
            else if (block.name === 'Glob') {
                try {
                    const { globby } = await import('globby');
                    const files = await globby(input.pattern, { cwd: PROJECT_ROOT, gitignore: true });
                    toolResults.push({ type: 'Glob', payload: { pattern: input.pattern, files: files.slice(0, 50) } });
                }
                catch (e) {
                    toolResults.push({ type: 'Glob', payload: { pattern: input.pattern, error: String(e) } });
                }
            }
        }
    }
    return { response: textResponse, toolResults };
}
